65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /**
68	     * Basic syntactic email check: a non-empty local part, an '@', and a domain containing at least
69	     * one dot, with no whitespace anywhere. Deliberately permissive but requires the essential shape.
70	     */
71	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
