90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        List<String> missingFields = new ArrayList<>();
120	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
121	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
122	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
123	        requireNonBlank(missingFields, "address", normalizedAddress);
124	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
125	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
126	        if (!missingFields.isEmpty()) {
127	            throw new MissingRequiredFieldsException(missingFields);
128	        }
129	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
130	        requireUniqueTelephone(normalizedTelephone);
131	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
132	        if (!sharesHousehold) {
133	            requireUniqueHousehold(ownerFieldsDto.getLastName(), normalizedAddress);
134	        }
135	        ownerFieldsDto.setTelephone(normalizedTelephone);
136	        if (ownerFieldsDto.getEmail() != null) {
137	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
138	        }
139	        HttpHeaders headers = new HttpHeaders();
140	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
141	        owner.setAddress(normalizedAddress);
142	        if (owner.getRegistrationDate() == null) {
143	            owner.setRegistrationDate(LocalDate.now());
144	        }
145	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
146	        if (sharesHousehold) {
147	            owner.setHouseholdId(joinHousehold(owner.getLastName(), owner.getAddress()));
148	        }
149	        this.clinicService.saveOwner(owner);
150	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
151	        headers.setLocation(UriComponentsBuilder.newInstance()
152	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
153	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
159	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
160	        if (currentOwner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        currentOwner.setAddress(ownerFieldsDto.getAddress());
164	        currentOwner.setCity(ownerFieldsDto.getCity());
165	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
166	        currentOwner.setLastName(ownerFieldsDto.getLastName());
167	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
168	        this.clinicService.saveOwner(currentOwner);
169	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
170	    }
