236	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
237	    @Override
238	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
239	        Owner owner = this.clinicService.findOwnerById(ownerId);
240	        if (owner != null) {
241	            Pet pet = owner.getPet(petId);
242	            if (pet != null) {
243	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
244	            }
245	        }
246	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
247	    }
248	
249	    /**
250	     * Builds the owner's customer code as {@code '<LAST3>-<NNNN>'}, where {@code LAST3} is the
251	     * upper-cased first three letters of {@code lastName} and {@code NNNN} is a global 4-digit
252	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
253	     *
254	     * @param lastName the owner's last name (already validated non-blank)
255	     * @return the formatted customer code for the owner being created
256	     */
257	    private String nextCustomerCode(String lastName) {
258	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
259	        int sequence = this.clinicService.findAllOwners().size() + 1;
260	        return String.format("%s-%04d", last3, sequence);
261	    }
262	
263	    /**
264	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
265	     * whitespace-only), so the caller can reject the request listing every offending field.
266	     */
267	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
268	        if (value == null || value.isBlank()) {
269	            missingFields.add(fieldName);
270	        }
271	    }
272	
273	    /**
274	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
275	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
276	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
277	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
278	     * {@code "+61412345678"}.
279	     *
280	     * @param telephone the raw telephone value from the request
281	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
282	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
283	     */
284	    private static String normalizeTelephone(String telephone) {
285	        String e164 = toE164(telephone);
286	        if (e164 == null) {
287	            throw new InvalidFieldValueException("telephone",
288	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
289	        }
290	        return e164;
291	    }
292	
293	    /**
294	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
295	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
296	     * owners' stored numbers when detecting duplicates.
297	     */
298	    private static String toE164(String telephone) {
299	        if (telephone == null) {
300	            return null;
301	        }
302	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
303	        String digits;
304	        if (cleaned.startsWith("+")) {
305	            digits = cleaned.substring(1);
306	        } else {
307	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
308	            digits = "61" + national;
309	        }
310	        if (!digits.matches("[0-9]{8,15}")) {
311	            return null;
312	        }
313	        return "+" + digits;
314	    }
315	
316	    /**
317	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
318	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
319	     *
320	     * @param email the raw email value from the request (already known to be non-null)
321	     * @return the lower-cased email to be stored and returned
322	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
323	     */
324	    private static String normalizeEmail(String email) {
325	        String trimmed = email.trim();
326	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
327	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
328	        }
329	        return trimmed.toLowerCase(Locale.ROOT);
330	    }
331	
332	    /**
333	     * Rejects the request when {@code normalizedTelephone} is already used by any existing owner,
334	     * comparing on the E.164 form so differently-formatted stored numbers still collide.
335	     *
336	     * @param normalizedTelephone the incoming owner's normalized E.164 telephone
337	     * @throws DuplicateTelephoneException if another owner already uses this telephone
338	     */
339	    private void requireUniqueTelephone(String normalizedTelephone) {
340	        boolean taken = this.clinicService.findAllOwners().stream()
341	            .map(Owner::getTelephone)
342	            .map(OwnerRestControllerV1::toE164)
343	            .filter(existing -> existing != null)
344	            .anyMatch(normalizedTelephone::equals);
345	        if (taken) {
346	            throw new DuplicateTelephoneException(normalizedTelephone);
347	        }
348	    }
349	
350	    /**
351	     * Rejects the request when another owner already shares this household, i.e. has both the same
352	     * last name and the same address once each value is normalized (trimmed, internal whitespace
353	     * runs collapsed to a single space, and compared case-insensitively). Callers skip this check
354	     * when the request opts in via {@code sharesHousehold}.
355	     *
356	     * @param lastName the incoming owner's last name (already validated non-blank)
357	     * @param address the incoming owner's address (already validated non-blank)
358	     * @throws DuplicateHouseholdException if another owner already has this last name and address
359	     */
360	    private void requireUniqueHousehold(String lastName, String address) {
361	        String normalizedLastName = normalizeForHousehold(lastName);
362	        String normalizedAddress = householdAddressKey(address);
363	        boolean taken = this.clinicService.findAllOwners().stream()
364	            .anyMatch(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
365	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress));
366	        if (taken) {
367	            throw new DuplicateHouseholdException(lastName, address);
368	        }
369	    }
370	
371	    /**
372	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
373	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
374	     * comparisons are case-insensitive.
375	     */
376	    private static String normalizeForHousehold(String value) {
377	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
378	    }
379	
380	    /**
381	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
382	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
383	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
384	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
385	     * value normalizes to the empty string, so the required-field check rejects an address that is
386	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
387	     *
388	     * @param address the raw address value from the request (may be {@code null})
389	     * @return the normalized address, or the empty string when blank after normalization
390	     */
391	    private static String normalizeAddress(String address) {
392	        if (address == null) {
393	            return "";
394	        }
395	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
396	        if (collapsed.isEmpty()) {
397	            return "";
398	        }
399	        String[] tokens = collapsed.split(" ");
400	        StringBuilder sb = new StringBuilder();
401	        for (String token : tokens) {
402	            String expanded = switch (token) {
403	                case "ST" -> "STREET";
404	                case "RD" -> "ROAD";
405	                case "AVE" -> "AVENUE";
406	                default -> token;
407	            };
408	            if (sb.length() > 0) {
409	                sb.append(' ');
410	            }
411	            sb.append(expanded);
412	        }
413	        return sb.toString();
414	    }
415	
416	    /**
417	     * Derives the comparison key for an address used by household-duplicate detection and the shared
418	     * household identifier: the address is first put in its canonical normalized form and then
419	     * lower-cased and whitespace-collapsed, so every comparison and the derived id agree on the
420	     * normalized address regardless of the raw casing, spacing or abbreviations supplied.
421	     */
422	    private static String householdAddressKey(String address) {
423	        return normalizeForHousehold(normalizeAddress(address));
424	    }
425	
426	    /**
427	     * Joins the household identified by this last name and address, returning the stable shared
428	     * {@code householdId} to store on the joining owner. The identifier is derived deterministically
429	     * from the normalized last name and address, so every owner in the same household resolves to the
430	     * same value. Any existing household members that predate this feature (or were created without
431	     * opting in) are back-filled with the shared identifier so the whole household agrees.
432	     *
433	     * @param lastName the joining owner's last name (already validated non-blank)
434	     * @param address the joining owner's address (already validated non-blank)
435	     * @return the shared household identifier for this last name and address
436	     */
437	    private String joinHousehold(String lastName, String address) {
438	        String normalizedLastName = normalizeForHousehold(lastName);
439	        String normalizedAddress = householdAddressKey(address);
440	        String householdId = householdIdFor(normalizedLastName, normalizedAddress);
441	        this.clinicService.findAllOwners().stream()
442	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
443	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress))
444	            .filter(existing -> !householdId.equals(existing.getHouseholdId()))
445	            .forEach(existing -> {
446	                existing.setHouseholdId(householdId);
447	                this.clinicService.saveOwner(existing);
448	            });
449	        return householdId;
450	    }
451	
452	    /**
453	     * Derives a stable household identifier from the already-normalized last name and address as the
454	     * upper-cased first 12 hex characters of their SHA-256 digest. Deterministic so the same household
455	     * always maps to the same identifier.
456	     */
457	    private static String householdIdFor(String normalizedLastName, String normalizedAddress) {
458	        try {
459	            byte[] digest = MessageDigest.getInstance("SHA-256")
460	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
461	            StringBuilder sb = new StringBuilder();
462	            for (byte b : digest) {
463	                sb.append(String.format("%02X", b));
464	            }
465	            return sb.substring(0, 12);
466	        }
467	        catch (NoSuchAlgorithmException e) {
468	            throw new IllegalStateException("SHA-256 not available", e);
469	        }
